From 47506997dc45edbc27b3a0e7c22935606ebcac98 Mon Sep 17 00:00:00 2001
From: Enrico Joerns <ejo@pengutronix.de>
Date: Fri, 2 Jun 2017 14:39:22 +0200
Subject: [PATCH] src/service: flush dbus interface to not drop property
 updates

This fixes a bug introduced by 7b27396055062ffbdb10a182d08465ed1f825f9d
where the call of `r_installer_set_operation()` was moved without moving
the associated call of `g_dbus_interface_skeleton_flush()`.

If not flushed, notifications for property updates will happen in and
idle loop. Thus multiple property updates might get aggregated.

If the same property is updated multiple times before a notification is
sent out, this will result in status update informations being lost.

A case where this could be observed quite often where the installation
status messages updates that randomly dropped some sub-steps from the
report.

Note that when introducing more fine-grained status updates (e.g.
reporting image write progress, progress updates may be performed
intentionally without calling the flush function in order to not DDoS
the d-bus interface.

Signed-off-by: Enrico Joerns <ejo@pengutronix.de>

diff --git a/src/service.c b/src/service.c
index 72d28da4..f025be1f 100644
--- a/src/service.c
+++ b/src/service.c
@@ -23,7 +23,6 @@ static gboolean service_install_notify(gpointer data) {
 	while (!g_queue_is_empty(&args->status_messages)) {
 		gchar *msg = g_queue_pop_head(&args->status_messages);
 		g_message("installing %s: %s", args->name, msg);
-		g_dbus_interface_skeleton_flush(G_DBUS_INTERFACE_SKELETON(r_installer));
 	}
 	g_mutex_unlock(&args->status_mutex);

@@ -42,6 +41,7 @@ static gboolean service_install_cleanup(gpointer data)
 	}
 	r_installer_emit_completed(r_installer, args->status_result);
 	r_installer_set_operation(r_installer, "idle");
+	g_dbus_interface_skeleton_flush(G_DBUS_INTERFACE_SKELETON(r_installer));
 	g_mutex_unlock(&args->status_mutex);

 	install_args_free(args);
@@ -66,6 +66,7 @@ static gboolean r_on_handle_install(RInstaller *interface,
 	args->cleanup = service_install_cleanup;

 	r_installer_set_operation(r_installer, "installing");
+	g_dbus_interface_skeleton_flush(G_DBUS_INTERFACE_SKELETON(r_installer));
 	res = install_run(args);
 	if (!res) {
 		goto out;
@@ -203,6 +204,7 @@ static void send_progress_callback(gint percentage,

 	progress_update_tuple = g_variant_new_tuple(progress_update, 3);
 	r_installer_set_progress(r_installer, progress_update_tuple);
+	g_dbus_interface_skeleton_flush(G_DBUS_INTERFACE_SKELETON(r_installer));
 }

 static void r_on_bus_acquired(GDBusConnection *connection,
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by the removal of the call to `g_dbus_interface_skeleton_flush()` from the `service_install_notify` function without appropriately moving it to other relevant functions. This led to property updates being aggregated in an idle loop, resulting in the loss of status update information when multiple updates occurred before a notification was sent out.

        Commit message:
        src/service: flush dbus interface to not drop property
 updates

This fixes a bug introduced by 7b27396055062ffbdb10a182d08465ed1f825f9d
where the call of `r_installer_set_operation()` was moved without moving
the associated call of `g_dbus_interface_skeleton_flush()`.

If not flushed, notifications for property updates will happen in and
idle loop. Thus multiple property updates might get aggregated.

If the same property is updated multiple times before a notification is
sent out, this will result in status update informations being lost.

A case where this could be observed quite often where the installation
status messages updates that randomly dropped some sub-steps from the
report.

Note that when introducing more fine-grained status updates (e.g.
reporting image write progress, progress updates may be performed
intentionally without calling the flush function in order to not DDoS
the d-bus interface.

Signed-off-by: Enrico Joerns <ejo@pengutronix.de>  

        Patch:

 static gboolean service_install_notify(gpointer data) {
 	RaucInstallArgs *args = data;

 	g_mutex_lock(&args->status_mutex);
 	while (!g_queue_is_empty(&args->status_messages)) {
 		gchar *msg = g_queue_pop_head(&args->status_messages);
 		g_message("installing %s: %s", args->name, msg);
-		g_dbus_interface_skeleton_flush(G_DBUS_INTERFACE_SKELETON(r_installer));
 	}
 	g_mutex_unlock(&args->status_mutex);

 	return G_SOURCE_REMOVE;
 }

 static gboolean service_install_cleanup(gpointer data)
 {
 	RaucInstallArgs *args = data;

 	g_mutex_lock(&args->status_mutex);
 	if (args->status_result == 0) {
 		g_message("installing `%s` succeeded", args->name);
 	} else {
 		g_message("installing `%s` failed: %d", args->name, args->status_result);
 	}
 	r_installer_emit_completed(r_installer, args->status_result);
 	r_installer_set_operation(r_installer, "idle");
+	g_dbus_interface_skeleton_flush(G_DBUS_INTERFACE_SKELETON(r_installer));
 	g_mutex_unlock(&args->status_mutex);

 	install_args_free(args);

 	return G_SOURCE_REMOVE;
 }

 static gboolean r_on_handle_install(RInstaller *interface,
 				    GDBusMethodInvocation  *invocation,
 				    const gchar *source) {
 	RaucInstallArgs *args = install_args_new();
 	gboolean res;

 	g_print("input bundle: %s\n", source);

 	res = !r_context_get_busy();
 	if (!res)
 		goto out;

 	args->name = g_strdup(source);
 	args->notify = service_install_notify;
 	args->cleanup = service_install_cleanup;

 	r_installer_set_operation(r_installer, "installing");
+	g_dbus_interface_skeleton_flush(G_DBUS_INTERFACE_SKELETON(r_installer));
 	res = install_run(args);
 	if (!res) {
 		goto out;
 	}
 	args = NULL;

 out:
 	g_clear_pointer(&args, g_free);
 	if (res) {
 		r_installer_complete_install(interface, invocation);
 	} else {
 		r_installer_set_operation(r_installer, "idle");
 		g_dbus_method_invocation_return_error(invocation,
 				 		      G_IO_ERROR,
 						      G_IO_ERROR_FAILED_HANDLED,
 						      "rauc installer error");
 	}

 	return TRUE;
 }


 static void send_progress_callback(gint percentage,
 				   const gchar *message,
 				   gint nesting_depth) {

 	GVariant **progress_update;
 	GVariant *progress_update_tuple;

 	progress_update = g_new(GVariant*, 3);
 	progress_update[0] = g_variant_new_int32(percentage);
 	progress_update[1] = g_variant_new_string(message);
 	progress_update[2] = g_variant_new_int32(nesting_depth);

 	progress_update_tuple = g_variant_new_tuple(progress_update, 3);
 	r_installer_set_progress(r_installer, progress_update_tuple);
+	g_dbus_interface_skeleton_flush(G_DBUS_INTERFACE_SKELETON(r_installer));
 }



